    if (old?.联系状态 === '已建立联系' && text(old.联系依据)) {
      set('联系状态', '已建立联系');
      if (!text(relation.联系依据)) set('联系依据', old.联系依据);
    }
    if (relation.联系状态 !== '已建立联系' || !text(relation.联系依据)) continue;
    if (initialLabel(relation.关系)) {
      set('关系', old && !initialLabel(old.关系) ? old.关系 : '已建立直接联系');
