  function readDateLabel(content) {
    const lines = content.split(/\r?\n/);
    let block = -1;
    for (let index = 0; index < Math.min(lines.length, 24); index++) {
      if (/^\s*(?:<[^>]+>\s*)?【(?:场景核心信息|基础信息)】\s*$/.test(lines[index])) { block = index; break; }
