  const fixed = new Set(['玩家', 'player', 'user', 'oc']);
  const displayStore = createPlayerDisplayStore({ storage, getContext });
  function context() {
    const ctx = getContext();
    const chatId = ctx?.getCurrentChatId?.() ?? ctx?.chatId;
